SELECT id,
  'A strong answer uses the STAR method: Situation (briefly set the context), Task (your specific responsibility), Action (what YOU did — use "I" not "we"), Result (quantify the outcome where possible). Example: "In my previous role as a junior engineer, we had a major deployment blocked by a flaky integration test I had never seen before (S). My task was to unblock the team within the afternoon (T). I isolated the test, traced it to a race condition in our async fixture setup, and wrote a deterministic mock (A). This fixed the deployment and I added the fix to our onboarding docs, preventing it for future engineers (R)."',
  ARRAY['STAR','situation','task','action','result','specific','quantify'],
  TRUE,
  '00000000-0000-0000-0000-000000000001'
FROM questions
WHERE text LIKE 'Tell me about a time you had to learn something new%'
  AND type = 'behavioral'
LIMIT 1;

SELECT id,
  'For a URL shortener: 1) Generate a short key (6-char base62 = 56bn combinations). 2) Hash the long URL (MD5/SHA) and store in a key-value store (Redis for hot paths, PostgreSQL for persistence). 3) Use a 301 redirect (or 302 if you need click analytics). Scale considerations: separate read and write paths; reads are 100:1 vs writes. Use CDN for popular URLs. Handle collisions with retry or counter-based generation. Mention: custom aliases, expiry TTLs, analytics pipeline (Kafka → ClickHouse). Design for 100M URLs/day = ~1157 QPS writes.',
  ARRAY['base62','key-value','Redis','CDN','301 redirect','hash','scale','QPS','analytics'],
  TRUE,
  '00000000-0000-0000-0000-000000000001'
FROM questions
WHERE text LIKE 'How would you design a URL shortener%'
  AND type = 'technical'
LIMIT 1;

